# Excluded security areas must remain byte-identical where applicable.
orig_env=os.getenv('MLR_ORIGINAL_DIR','').strip()
if orig_env:
    orig=Path(orig_env)
    for rel in ['includes/secret-editor/mlr-secret-editor.php','includes/secret-editor/edit-form.php']:
        if (orig/rel).exists() and (root/rel).exists():
            ck(f'excluded unchanged: {rel}', hashlib.sha256((orig/rel).read_bytes()).digest()==hashlib.sha256((root/rel).read_bytes()).digest())
    rel='includes/ajax/secret-editor-actions.php'
    if (orig/rel).exists() and (root/rel).exists():
        import difflib
        old_lines=(orig/rel).read_text(errors='replace').splitlines()
        new_lines=(root/rel).read_text(errors='replace').splitlines()
        changed=[]
        for line in difflib.unified_diff(old_lines,new_lines,n=0):
            if line.startswith(('---','+++','@@')): continue
            if line.startswith(('+','-')): changed.append(line[1:].strip())
        allowed_fragments=('installment_plans ORDER BY name','mlr_get_installment_plan_order_by_sql','installment_plans {$plan_order_sql}')
        ck('secret editor security logic unchanged; at most plan-order query differences allowed', (not changed) or all(any(frag in line for frag in allowed_fragments) for line in changed), ' | '.join(changed))
    rel='includes/loan-calculations.php'
    if (orig/rel).exists() and (root/rel).exists():
        ck('core financial formula file byte-identical to original', hashlib.sha256((orig/rel).read_bytes()).digest()==hashlib.sha256((root/rel).read_bytes()).digest())
    # Compare exact credential-definition/candidate region, while allowing later API hardening changes.
    o=(orig/'includes/functions.php').read_text(errors='replace'); w=func
    def cred_region(s):
        a=s.find("if (!defined('MLR_ICS24_USERNAME'))")
        b=s.find("if (!function_exists('mlr_ics24_get_base_url'))",a)
        return s[a:b] if a>=0 and b>a else ''
    ck('excluded unchanged: ICS24 hardcoded credential block', cred_region(o)!='' and cred_region(o)==cred_region(w))

